from functools import lru_cache
from pydantic_settings import BaseSettings, SettingsConfigDict

class Settings(BaseSettings):
    app_name: str = "FastAPI Demo API"
    app_version: str = "1.0.0"
    debug: bool = False
    database_url: str = "postgresql+psycopg2://user:pass@db:5432/demo_db"

    model_config = SettingsConfigDict(env_file=".env", env_file_encoding="utf-8")

@lru_cache
def get_settings() -> Settings:
    return Settings()

from fastapi import APIRouter, HTTPException, status
from app.models import Item
from app.schemas import ItemCreate, ItemRead, ItemUpdate

router = APIRouter(prefix="/items", tags=["items"])
_items: dict[int, Item] = {}
_next_id = 1

@router.post("", response_model=ItemRead, status_code=status.HTTP_201_CREATED)
def create_item(payload: ItemCreate) -> ItemRead:
    global _next_id
    item = Item(id=_next_id, **payload.model_dump())
    _items[item.id] = item
    _next_id += 1
    return ItemRead.model_validate(item)

@router.get("", response_model=list[ItemRead])
def list_items() -> list[ItemRead]:
    return [ItemRead.model_validate(i) for i in _items.values()]

@router.get("/{item_id}", response_model=ItemRead)
def get_item(item_id: int) -> ItemRead:
    item = _items.get(item_id)
    if item is None:
        raise HTTPException(status_code=404, detail="Item not found")
    return ItemRead.model_validate(item)

@router.patch("/{item_id}", response_model=ItemRead)
def update_item(item_id: int, payload: ItemUpdate) -> ItemRead:
    item = _items.get(item_id)
    if item is None:
        raise HTTPException(status_code=404, detail="Item not found")
    updated = item.model_copy(update={k: v for k, v in payload.model_dump(exclude_unset=True).items() if v is not None})
    _items[item_id] = updated
    return ItemRead.model_validate(updated)

@router.delete("/{item_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_item(item_id: int) -> None:
    if item_id not in _items:
        raise HTTPException(status_code=404, detail="Item not found")
    del _items[item_id]

from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from app.config import get_settings
from app.routers import items

settings = get_settings()
app = FastAPI(title=settings.app_name, version=settings.app_version)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)
app.include_router(items.router)

@app.get("/", tags=["meta"])
def root() -> dict:
    return {"name": settings.app_name, "version": settings.app_version}

@app.get("/health", tags=["meta"])
def health() -> dict:
    return {"status": "ok"}
